from datetime import datetime

from lfx.custom.custom_component.component import Component
from lfx.io import Output
from lfx.schema.message import Message
from lfx.schema.data import Data


class CreateRunFolder(Component):
    display_name = "Create Run Folder"
    name = "CreateRunFolder"
    icon = "folder"

    outputs = [
        Output(
            name="folder_message",
            display_name="Folder Message",
            method="build_message",
        ),
        Output(
            name="folder_data",
            display_name="Folder Data",
            method="build_data",
        ),
    ]

    def _get_folder_name(self) -> str:
        if hasattr(self, "_cached_folder_name") and self._cached_folder_name:
            return self._cached_folder_name

        self._cached_folder_name = datetime.now().strftime("%Y%m%d_%H%M%S")
        return self._cached_folder_name

    def build_message(self) -> Message:
        folder_name = self._get_folder_name()
        return Message(text=folder_name)

    def build_data(self) -> Data:
        folder_name = self._get_folder_name()
        return Data(data={"run_folder": folder_name})
